  "claims": [
    {
      "claim": "The most transferable human absolute-bioavailability contexts for this lipophilic, poorly soluble heteroaromatic query are at or above the F=20% threshold: vismodegib 31.8%, dasatinib modeled 20–28% and reported 34%, erlotinib ~59%, bosentan ~50%, sildenafil 41%, and celecoxib kinetically estimated 0.72.",
      "card_ids": ["C62","C64","C167","C37","C60","C34","C41","C70","C19","C25","C56","C80","C43","C69"]
